-- ============================================================
-- MIGRATION : Structure sous-catégories UUID
-- Généré automatiquement le 2026-04-03T08:04:11.701Z
-- ============================================================

-- ============================================================
-- PHASE 1 : Ajouter la colonne category_uuid
-- ============================================================

ALTER TABLE public.categories
  ADD COLUMN IF NOT EXISTS category_uuid UUID DEFAULT gen_random_uuid();

UPDATE public.categories
  SET category_uuid = gen_random_uuid()
  WHERE category_uuid IS NULL;

ALTER TABLE public.categories
  ALTER COLUMN category_uuid SET NOT NULL;

-- ============================================================
-- PHASE 2 : Remplir category_uuid pour les catégories existantes
-- à partir de l'id si c'est un UUID, sinon générer
-- ============================================================

UPDATE public.categories
  SET category_uuid = id
  WHERE id::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

UPDATE public.categories
  SET category_uuid = gen_random_uuid()
  WHERE category_uuid IS NULL;

-- ============================================================
-- PHASE 3 : Ajouter la colonne subcategory_uuid
-- Announcements.subcategory_id reste en TEXT (slug) pour
-- la compatibilité URL, mais subcategory_uuid stocke l'UUID
-- ============================================================

ALTER TABLE public.announcements
  ADD COLUMN IF NOT EXISTS subcategory_uuid UUID;

-- ============================================================
