-- ============================================================
-- PHASE 6 : Index et contraintes
-- ============================================================

CREATE UNIQUE INDEX IF NOT EXISTS idx_categories_category_uuid ON public.categories(category_uuid);
CREATE INDEX IF NOT EXISTS idx_categories_parent_uuid ON public.categories(parent_id);
CREATE INDEX IF NOT EXISTS idx_categories_slug ON public.categories(slug);
CREATE INDEX IF NOT EXISTS idx_announcements_subcategory_uuid ON public.announcements(subcategory_uuid);

-- ============================================================
-- PHASE 7 : Trigger de sync auto subcategory_uuid
-- Quand on insère une annonce avec subcategory_id (slug),
-- on resolve automatiquement le subcategory_uuid
-- ============================================================

CREATE OR REPLACE FUNCTION public.resolve_subcategory_uuid()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.subcategory_id IS NOT NULL AND NEW.subcategory_uuid IS NULL THEN
    SELECT c.category_uuid INTO NEW.subcategory_uuid
    FROM public.categories c
    WHERE c.slug = NEW.subcategory_id
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_resolve_subcategory_uuid ON public.announcements;
CREATE TRIGGER trg_resolve_subcategory_uuid
  BEFORE INSERT OR UPDATE OF subcategory_id ON public.announcements
  FOR EACH ROW
  EXECUTE FUNCTION public.resolve_subcategory_uuid();

